export function enhanceIllustration(id,workbench,tags){
 if(id==='web'){
  const preview=workbench.querySelector('.website-preview');preview.classList.add('detailed-preview');preview.setAttribute('aria-label','Màn hình mẫu minh họa dịch vụ website');
  const explanation=document.createElement('div');explanation.className='web-explanation';const detail=workbench.querySelector('.service-detail');detail.before(explanation);explanation.append(detail);
  const deliverables=document.createElement('div');deliverables.className='web-deliverables';explanation.append(deliverables);
  const outputs=[['Tổ chức thông tin','Giới thiệu, dịch vụ, dự án và liên hệ trong một cấu trúc rõ ràng.','Tiếp nhận nhu cầu','Biểu mẫu dẫn yêu cầu tới đội ngũ phụ trách.','Chủ động cập nhật','Quản trị trang và nội dung sau khi bàn giao.'],['Thông điệp nhất quán','Quảng cáo và trang đích cùng một lời hứa giá trị.','Hành động tập trung','Một biểu mẫu phù hợp với mục tiêu chiến dịch.','Theo dõi chuyển đổi','Kiểm tra nguồn truy cập và yêu cầu nhận về.'],['Hệ thống thiết kế','Kiểu chữ, màu sắc và thành phần dùng nhất quán.','Luồng thao tác','Từng bước giúp khách hàng tìm hiểu và liên hệ.','Kiểm tra trải nghiệm','Rà soát khả năng đọc và sử dụng trên nhiều màn hình.'],['Nền tảng tìm kiếm','Cấu trúc trang, tiêu đề và liên kết nội bộ.','Hiệu suất tải trang','Rà soát tài nguyên và trải nghiệm di động.','Vận hành dài hạn','Hướng dẫn cập nhật, sao lưu và theo dõi.']];
  const render=i=>{const o=outputs[i];deliverables.innerHTML='<span class="deliverable-label">TỪ THIẾT KẾ ĐẾN SỬ DỤNG</span>'+[0,2,4].map((n,j)=>`<div><b>0${j+1}</b><p><strong>${o[n]}</strong><span>${o[n+1]}</span></p></div>`).join('');preview.dataset.screen=String(i);preview.innerHTML=screens[i]+'<div class="sample-caption">BẢN THIẾT KẾ MINH HỌA / '+['WEBSITE','LANDING PAGE','UX/UI','SEO'][i]+'</div>';};render(0);
  tags.addEventListener('click',e=>{const b=e.target.closest('button');if(b)render(Number(b.dataset.index));});
 }
 if(id==='ai')workbench.querySelector('.automation-guards').insertAdjacentHTML('beforebegin','<div class="agent-example"><span>TÌNH HUỐNG MINH HỌA</span><div><b>KHÁCH HÀNG</b><p>Tôi cần một website để tiếp nhận yêu cầu tư vấn.</p></div><i>↓ Tra cứu kiến thức · Xác định nhu cầu</i><div><b>AI → NHÂN VIÊN</b><p>Tóm tắt nhu cầu, lưu ngữ cảnh và chuyển đội ngũ tư vấn.</p></div></div>');
 if(id==='data')workbench.querySelectorAll('.crm-pipeline li').forEach((col,i)=>col.insertAdjacentHTML('beforeend','<div class="crm-record"><span class="record-avatar">'+['IN','TO','CX','OK'][i]+'</span><div><b>'+['Yêu cầu từ website','Nhân sự phụ trách','Nội dung trao đổi','Lịch chăm sóc'][i]+'</b><small>'+['Nguồn • Nhu cầu','Phân công • Thời hạn','Ghi chú • Lịch hẹn','Phản hồi • Bước tiếp'][i]+'</small></div></div>'));
 if(id==='ads')workbench.querySelector('.conversion-funnel').insertAdjacentHTML('beforeend','<div class="ad-creative"><span>MẪU THÔNG ĐIỆP QUẢNG CÁO</span><strong>Đúng nhu cầu.<br>Đúng thời điểm.</strong><small>Lợi ích rõ ràng · Một hành động tiếp theo</small><b>Khám phá giải pháp ↗</b></div>');
 if(id==='social')workbench.querySelector('.editorial-cover').insertAdjacentHTML('beforeend','<div class="editorial-stamp"><span>NỘI DUNG</span><b>Ý tưởng → Câu chuyện → Kết nối</b></div>');
}
